(function () {
  'use strict';
  const chunkSet = {"title":"Revising & Editing Strategy","topic":"Grammar & Usage","questions":[{"id":"grammar-revising-editing-strategy-q0201","version":4,"contentHash":"sha256:f3d001a224864b24ff48fb8311b586ddaf5e41c8071a87d156245d35ec3bc13c","question":"Which of the following details is a word that does not express emotion?","choices":["confused","lonely","bashful","quick"],"correct":3,"explanation":{"correct":"Answer: quick. This word describes the speed of an action or object rather than a feeling. It is a physical descriptor, not an emotional state.","incorrect":[{"choice":"confused","category":"emotional state","reason":"This word describes a feeling of being puzzled or uncertain. Since it represents how someone feels, it is an emotion-based word."},{"choice":"lonely","category":"emotional state","reason":"This word describes the feeling of sadness because one is alone. It is a state of mind or heart, making it an emotion."},{"choice":"bashful","category":"emotional state","reason":"This word describes someone who is shy or uncomfortable around others. Because it refers to a personality trait or emotional response, it is an emotion-based word."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":201,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":6,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Words that express emotion describe how a person feels, thinks, or reacts to a situation. Descriptive words can also relate to physical qualities like size, speed, or color, which are not emotions.","example":"Emotional: happy, sad, angry. Non-emotional: tall, fast, square.","strategyClue":"Ask yourself: 'Can I feel this word?' If you can imagine someone experiencing that word as a feeling in their heart or mind, it is an emotion.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0202","version":4,"contentHash":"sha256:0a250bcc31c834f0584c104dcdf6f1460d83625bc09002852d8266f44bcf0ab8","question":"Which sentence tells me how big wolves are?","choices":["Wolves like to live together.","Howling is how wolves talk to each other.","Most dogs are smaller than wolves.","You can find wolves in the United States."],"correct":2,"explanation":{"correct":"Answer: Most dogs are smaller than wolves. This sentence uses a comparison to help the reader understand the relative size of a wolf compared to a dog.","incorrect":[{"choice":"Wolves like to live together.","category":"Incorrect information type","reason":"This sentence describes a social habit of wolves, not their physical size or dimensions."},{"choice":"Howling is how wolves talk to each other.","category":"Incorrect information type","reason":"This sentence describes how wolves communicate through sound, which does not provide information about how large or small their bodies are."},"",{"choice":"You can find wolves in the United States.","category":"Incorrect information type","reason":"This sentence tells you the geographical location where wolves live, not their physical measurements."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":202,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":8,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Sentences that explain size use comparison words or measurements to show how big or small something is.","example":"The elephant is taller than the giraffe. The mouse is smaller than a house cat. My backpack is heavier than my pencil case.","strategyClue":"Look for words in the sentences that compare things, such as 'bigger,' 'smaller,' 'taller,' or 'shorter,' to identify which one focuses on size.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0203","version":4,"contentHash":"sha256:b67c5f5d4e94f020dcc2fc8055781638bf6c56027b86512c487f21a1c132285e","question":"Pick the listof items that belong in a school.","choices":["ladder, hay, rake","ruler, janitor, notebook","shopping cart, milk, cashier","oil, tires, wrench"],"correct":1,"explanation":{"correct":"Answer: ruler, janitor, notebook. These items and roles are commonly found in a school building, which is a place of learning.","incorrect":[{"choice":"ladder, hay, rake","category":"farm setting items","reason":"These items are typically found on a farm or in a barn, not in a school classroom or building."},"",{"choice":"shopping cart, milk, cashier","category":"grocery store setting","reason":"These items and roles are associated with a grocery store or supermarket, not a school."},{"choice":"oil, tires, wrench","category":"mechanic shop setting","reason":"These tools and supplies are used by mechanics to fix vehicles, which does not match the school environment."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":203,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":18,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Words can be grouped into categories based on their context or where you might typically find them.","example":"Kitchen items: spoon, plate, oven. Playground items: slide, swing, ball.","strategyClue":"Visualize each location mentioned in the options and imagine walking through the building; ask yourself if you would logically see these three things there at the same time.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0204","version":5,"contentHash":"sha256:e940fa343af821c1a4e0fa533b2c9125fb54c16ed8d137eeb2a1cbb605fdf0a2","question":"Choose the best missing word. The grass _____ wet this morning.","choices":["is","be","are","can"],"correct":0,"explanation":{"correct":"Answer: is. The word 'grass' is a singular noun representing one collective thing. We use the singular verb 'is' to match the singular subject.","incorrect":["",{"choice":"be","category":"verb form error","reason":"The word 'be' is the base form and does not work here. In the present tense, we must change 'be' to 'is' when talking about a singular subject like 'grass'."},{"choice":"are","category":"subject-verb disagreement","reason":"We use 'are' for plural subjects, such as 'The flowers' or 'They'. Since 'grass' is a singular noun, 'are' does not correctly match the subject."},{"choice":"can","category":"improper modal usage","reason":"'Can' describes an ability or possibility, which doesn't fit the sentence's description of a state of being. 'Is' describes the condition of the grass."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":204,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Subjects and verbs must agree in number; singular subjects take singular verbs, and plural subjects take plural verbs.","example":"The dog is happy. The dogs are happy. My friend is here.","strategyClue":"Look at the subject of the sentence and ask yourself, 'Is this one thing or more than one?' If it is one thing, choose the verb that describes a singular state.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-revising-editing-strategy-q0205","version":4,"contentHash":"sha256:bc66feb93d58ad7c5f5fec2c421fb7f8b4db8bfe464f99d5dc7867e9aac29c8a","question":"Choose the last step for how to w ash dishes.","choices":["fill the sink with hot water","dry the dishes","use a sponge to clean the dishes","add soap to the water"],"correct":1,"explanation":{"correct":"Answer: dry the dishes. This is the correct final step in the sequence because you must wash and rinse the dishes before they can be dried.","incorrect":[{"choice":"fill the sink with hot water","category":"chronological order","reason":"This action happens at the very beginning of the process to prepare the cleaning supplies, not at the end."},"",{"choice":"use a sponge to clean the dishes","category":"sequencing error","reason":"Cleaning the dishes with a sponge happens in the middle of the process, after the soap and water are ready but before they are dried."},{"choice":"add soap to the water","category":"sequencing error","reason":"Adding soap is part of the setup process that must happen before you can start washing the dishes."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":205,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":22,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A process is a series of steps that happen in a specific order to reach a goal. You must finish the preparation and cleaning steps before you can do the finishing step.","example":"1. Put on socks, 2. Put on shoes, 3. Tie laces (not 1. Tie laces, 2. Put on shoes).","strategyClue":"Think about what physical state the object needs to be in to finish the task. You cannot dry dishes until the cleaning part is completely finished.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0206","version":4,"contentHash":"sha256:d04207b0e1e121a2e0d11035b6225651f8ec34915fdb382a623919bc6ae8bfe3","question":"Identify the words that add details to the topic. The _____ cake was _____.","choices":["sweet, clear","birthday, pie","ice cream, yummy","pie, clear"],"correct":2,"explanation":{"correct":"Answer: ice cream, yummy. These words provide descriptive details about the noun 'cake', telling us what kind of cake it is and how it tastes.","incorrect":[{"choice":"sweet, clear","category":"illogical adjective","reason":"While 'sweet' describes the cake, 'clear' is not a way to describe how a cake looks or tastes. The second word needs to describe the cake's quality."},{"choice":"birthday, pie","category":"noun as descriptor","reason":"While 'birthday' is a type of cake, 'pie' is a completely different dessert. A cake cannot be a pie, so this combination does not make sense."},"",{"choice":"pie, clear","category":"category mismatch","reason":"This choice uses a different dessert ('pie') to describe a cake and an adjective ('clear') that doesn't fit the context of describing food."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":206,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":24,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Adjectives and descriptive nouns add detail by telling us more about the properties, flavors, or types of a noun.","example":"The chocolate (type) cake was delicious (quality). The tiny (size) kitten was soft (texture).","strategyClue":"Test each option by reading the sentence aloud to see if the first word correctly labels the type of item and the second word effectively describes how it tastes or feels.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0207","version":5,"contentHash":"sha256:f1aa77301d6191b48cee26fbecd8d74246c60762bb511141f306de107e78c26d","question":"Which thing does not belong?","choices":["tulip","plant","rose","daisy"],"correct":1,"explanation":{"correct":"Answer: plant. While tulips, roses, and daisies are all specific types of flowers, 'plant' is the broad, general category that includes them all.","incorrect":[{"choice":"tulip","category":"specific flower type","reason":"A tulip is a specific type of flower, just like the other flowers in the list. It belongs in the group of flowers, so it is not the odd one out."},"",{"choice":"rose","category":"specific flower type","reason":"A rose is a specific kind of flower. Since it shares the same category as a daisy and a tulip, it is not the item that does not belong."},{"choice":"daisy","category":"specific flower type","reason":"A daisy is a specific type of flower. Because it fits perfectly into the category of 'flowers' along with the other choices, it is not the answer."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":207,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":27,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To find the item that does not belong, identify the category that most of the items share, then find the item that is either too broad or from a different group entirely.","example":"Dog, cat, hamster, mammal (mammal is the category); Apple, banana, carrot, grape (carrot is a vegetable, not a fruit).","strategyClue":"Label each item with a specific name. If three items share a narrow, specific category and one item is a general name for the whole group, the general name is the outlier.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0208","version":4,"contentHash":"sha256:e775a993b27a1a037daab9fe9b62696d8820fc21d780a4b4edfaa3b9a57d290e","question":"Choose the words that best complete the following sentence. The popcorn at the movie was good; it was __ ___.","choices":["dry andold","cold and mushy","warm and salty","warm and stale"],"correct":2,"explanation":{"correct":"Answer: warm and salty. Popcorn is traditionally served warm and salty, making these adjectives the best fit to describe a positive experience at the movie theater.","incorrect":[{"choice":"dry andold","category":"missing space / spelling","reason":"This choice contains a typo with the words 'andold' joined together. Additionally, 'dry' popcorn is generally not considered good."},{"choice":"cold and mushy","category":"inconsistent adjectives","reason":"These adjectives describe popcorn that is unappealing or spoiled. Since the sentence says the popcorn was 'good', these words do not make sense."},"",{"choice":"warm and stale","category":"contradictory adjectives","reason":"While 'warm' is a good quality for popcorn, 'stale' means old and unpleasant. You wouldn't describe 'good' popcorn as stale."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":208,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Adjectives are words that describe nouns. When choosing adjectives for a sentence, they must make logical sense and fit the positive or negative tone of the context.","example":"The fresh apple was crisp and sweet. The broken toy was sharp and dangerous.","strategyClue":"Look at the tone set by the first part of the sentence (the word 'good'). Ask yourself which pair of words describes a pleasant food experience.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0209","version":5,"contentHash":"sha256:facdb12117ceb4adc05e84f729493c1729fd58d7a5666d6a020cf037490d935a","question":"Which word does not belong in this sentence? I have got no idea what the answer is.","choices":["have","got","no","is"],"correct":1,"explanation":{"correct":"Answer: got. In standard English, the phrase 'I have no idea' is complete. Including 'got' creates a redundancy because 'have' already expresses possession or existence.","incorrect":[{"choice":"have","category":"essential verb","reason":"The word 'have' is the main verb of the sentence. Without it, the sentence 'I no idea...' would be missing its action or state of being."},"",{"choice":"no","category":"essential modifier","reason":"The word 'no' acts as an adjective describing the noun 'idea.' Without it, the sentence 'I have idea' does not convey the intended meaning."},{"choice":"is","category":"linking verb","reason":"The word 'is' connects the subject 'answer' to the description 'what the answer is.' It is a necessary part of the noun clause in this sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":209,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Words that provide the same meaning are redundant. In formal English, choose the most direct way to state an idea rather than using extra, unnecessary words.","example":"Correct: 'I have an idea.' Incorrect: 'I have got an idea.' Correct: 'She has a car.' Incorrect: 'She has got a car.'","strategyClue":"Try removing each word from the sentence one by one to see if the sentence still makes sense and sounds professional. Look for words that feel like 'extra' baggage that don't add new information.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0210","version":4,"contentHash":"sha256:58342f71ea7ce100a1ba31aa9eb096ee6dde26028cb0244162ff90ca5705e3f2","question":"Which of the following would be included under the topic of getting dressed?","choices":["backpack","washcloth","socks","pillow"],"correct":2,"explanation":{"correct":"Answer: socks. Socks are an essential item of clothing that you put on your feet as part of getting dressed.","incorrect":[{"choice":"backpack","category":"category mismatch","reason":"A backpack is a tool used for carrying items, not an article of clothing you wear on your body to get dressed."},{"choice":"washcloth","category":"category mismatch","reason":"A washcloth is used for cleaning or bathing, not for wearing as clothing."},"",{"choice":"pillow","category":"category mismatch","reason":"A pillow is a piece of bedding used for sleep, not an item of clothing worn while getting dressed."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":210,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":33,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Getting dressed involves putting on items meant to cover, protect, or decorate the body.","example":"Correct: shirt, pants, shoes. Incorrect: toothbrush (hygiene), blanket (bedding).","strategyClue":"Ask yourself: 'Is this an object I wear on my body to go out?' If the answer is yes, it belongs in the getting dressed category.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0211","version":4,"contentHash":"sha256:66bcc2ecd5eccd7fc5c8607d434bb4fe0e95bf9f334a7cfd18e12402d39085a7","question":"Which word shows the cat had eaten a lot?","choices":["shaking","relaxed","active","stuffed"],"correct":3,"explanation":{"correct":"Answer: stuffed. The word 'stuffed' describes being filled to capacity, which fits the context of the cat having eaten a lot of food.","incorrect":[{"choice":"shaking","category":"incorrect descriptive verb","reason":"Shaking suggests movement, fear, or coldness, not the feeling of having eaten a large amount of food."},{"choice":"relaxed","category":"incorrect emotional state","reason":"While a cat might be relaxed after eating, 'relaxed' describes a mood or state of rest rather than the physical sensation of being full."},{"choice":"active","category":"incorrect energy level","reason":"Active means the cat is energetic or moving around, which is the opposite of the feeling of having eaten a very large meal."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":211,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Descriptive adjectives help us explain how a person or animal feels after an action, such as eating a big meal.","example":"He felt hungry after school. The kitten felt sleepy after playing. The dog felt stuffed after his giant bowl of kibble.","strategyClue":"Imagine the cat's belly after the meal. Ask yourself which word describes the physical sensation of being full rather than how the cat is acting or moving.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0212","version":4,"contentHash":"sha256:74748548f5a740244e4bfeae3987b947869bc2bc0062bc5c44181aad56510e4d","question":"What is the subjectof this sentence? The dog chased the squirrel.","choices":["The","dog","chased","squirrel"],"correct":1,"explanation":{"correct":"Answer: dog. The subject is the person, animal, or thing that is performing the action in the sentence. In this sentence, the dog is the one doing the chasing.","incorrect":[{"choice":"The","category":"article error","reason":"'The' is an article, not the subject. It is just a helper word that describes the noun 'dog'."},"",{"choice":"chased","category":"verb error","reason":"'Chased' is the action word, or verb, of the sentence, not the subject performing the action."},{"choice":"squirrel","category":"object error","reason":"The squirrel is the object of the sentence because it is the one receiving the action, not the one performing it."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":212,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The subject is the part of the sentence that tells you who or what is performing the action.","example":"The cat slept. (Subject: cat); The boy ran. (Subject: boy); The sun shines. (Subject: sun)","strategyClue":"Find the action word (the verb) in the sentence and ask yourself 'Who or what performed this action?' The answer to that question is your subject.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0213","version":4,"contentHash":"sha256:3771ad2a5b9e769aa05c2a14dc228427e2cb8f646be189f78a2c3b4ca762c8a2","question":"Which sentence below shows that Donny is confused?","choices":["Donny bought ham and milk at the store.","After work, Donny went to the gym.","Donny didn’t know which way to turn.","That morning, Donny was very tired."],"correct":2,"explanation":{"correct":"Answer: Donny didn’t know which way to turn. The phrase 'didn't know' indicates a state of uncertainty or confusion, which perfectly matches the question's requirement.","incorrect":[{"choice":"Donny bought ham and milk at the store.","category":"descriptive sentence focus","reason":"This sentence describes a simple action of grocery shopping. It does not contain any information or context that suggests Donny is confused."},{"choice":"After work, Donny went to the gym.","category":"simple action sequence","reason":"This choice describes a routine activity. Going to the gym is a clear, planned action that does not show signs of being lost or puzzled."},"",{"choice":"That morning, Donny was very tired.","category":"describing a physical state","reason":"Being 'tired' describes how Donny feels physically, but it is different from being confused. Confusion refers to the mind not knowing what to do, whereas being tired refers to needing rest."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":213,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":41,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To identify an emotion or state of mind, look for verbs and adjectives that describe someone's thoughts, feelings, or knowledge.","example":"Confused: 'He was puzzled by the riddle.' Tired: 'She yawned because she was sleepy.' Happy: 'He smiled when he won the game.'","strategyClue":"Look at each sentence and ask yourself: 'Does this show someone knowing what to do, or does it show someone stuck?' Only one sentence shows someone who is stuck or unsure.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0214","version":4,"contentHash":"sha256:1bcd8d8a65dab146df2c3011ea7773fce730765d575dd8592a40af39f9b23374","question":"What is the subjectof the sentence? The dishwasher stopped working.","choices":["The","dishwasher","stopped","working"],"correct":1,"explanation":{"correct":"Answer: dishwasher. The subject of a sentence is the person, place, thing, or idea that is doing the action or being described. In this sentence, the dishwasher is the noun performing the action of stopping.","incorrect":[{"choice":"The","category":"article error","reason":"'The' is an article used to point to a noun, but it is not the noun itself. It identifies the dishwasher, but cannot act as the subject of the sentence."},"",{"choice":"stopped","category":"verb identification","reason":"'Stopped' is the verb (the action) in this sentence. The subject is the thing that did the stopping, not the action itself."},{"choice":"working","category":"verb form error","reason":"'Working' describes what the dishwasher stopped doing. It is part of the verb phrase, not the noun performing the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":214,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":50,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The subject is the main noun or pronoun that performs the action in a sentence. It answers the question 'Who or what is the sentence about?'","example":"The dog barked. (Subject: dog). The sun is shining. (Subject: sun). My teacher smiled. (Subject: teacher).","strategyClue":"Find the action word (the verb) in the sentence first. Then, ask yourself 'Who or what did this action?' to identify the subject.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0215","version":5,"contentHash":"sha256:f8c6e71cc1828440d4e611da380a3b090595e5de357386995aee8ff9dd15c29f","question":"Which sentence does not indicate a moodor a tone?","choices":["His h ouse is hot and stuffy.","I feel sleepy and tired.","It is cold and damp outside.","The airplane is arriving on time."],"correct":3,"explanation":{"correct":"Answer: The airplane is arriving on time. This sentence provides a factual, neutral update about a schedule. It does not contain descriptive words that express a speaker's personal feeling or the atmospheric quality of a setting.","incorrect":[{"choice":"His h ouse is hot and stuffy.","category":"expresses physical discomfort","reason":"The words 'hot' and 'stuffy' describe the condition of the house, which creates a specific uncomfortable mood or tone for the person inside."},{"choice":"I feel sleepy and tired.","category":"expresses internal state","reason":"The words 'sleepy' and 'tired' directly state the internal mood or physical state of the speaker."},{"choice":"It is cold and damp outside.","category":"describes atmospheric tone","reason":"The words 'cold' and 'damp' describe the weather, which creates a gloomy or chilly tone for the reader."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":215,"sourceFile":"Basic-3_Writing strategies_Application_Style.pdf","sourceQuestionNumber":1,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Mood and tone are conveyed through sensory details and feeling words that suggest an attitude, atmosphere, or emotional state. A purely objective statement of fact lacks these emotional markers.","example":"Factual: The car is parked. (Neutral) vs. The car is broken and abandoned. (Gloomy mood).","strategyClue":"Highlight every adjective in the sentence. If the adjectives describe facts (like time or location) that leave no room for feeling, it is a neutral statement.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0216","version":4,"contentHash":"sha256:a09abfe1005cc89e483b4503ce2e692f8b686990db664f3013b0d985ebb3f73f","question":"Identify the sentence that has a directobject.","choices":["Nadia ran fast.","Nadia is nice.","Nadiaread the book.","N adia fell."],"correct":2,"explanation":{"correct":"Answer: Nadia read the book. A direct object is a noun or pronoun that receives the action of a verb. In this sentence, 'the book' is the object being read by Nadia.","incorrect":[{"choice":"Nadia ran fast.","category":"adverb usage","reason":"'Fast' describes *how* Nadia ran, making it an adverb. It does not answer 'what' or 'who' is receiving the action of the verb."},{"choice":"Nadia is nice.","category":"linking verb","reason":"'Is' is a linking verb that connects the subject to an adjective ('nice'). It does not show an action being done to an object."},"",{"choice":"N adia fell.","category":"intransitive verb","reason":"The verb 'fell' is intransitive here, meaning it does not transfer action to an object. There is no noun receiving the falling."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":216,"sourceFile":"Basic-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A direct object is the noun or pronoun that receives the action of a transitive verb. It answers the question 'What?' or 'Who?' after the verb.","example":"He kicked the ball (Kicked what? The ball). She ate an apple (Ate what? An apple).","strategyClue":"Find the verb in the sentence and ask 'What?' or 'Who?' immediately after it. If there is a noun in the sentence that answers that question, you have found the direct object.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0217","version":4,"contentHash":"sha256:f0814911b16d4f1d895713f40185fc04fe44bf94a257d501b065347ee09bcb0f","question":"Identify the sentence that is a complete thought.","choices":["Is coldoutside?","Outside cold is today?","Is it coldoutside today?","Today coldoutside?"],"correct":2,"explanation":{"correct":"Answer: Is it cold outside today?. A complete sentence must have a subject and a verb working together to express a full thought. This choice includes the subject 'it' and the verb 'is' to form a clear, complete question.","incorrect":[{"choice":"Is coldoutside?","category":"missing subject","reason":"This sentence is missing a subject. We need to know who or what is cold, such as 'the air' or 'it'."},{"choice":"Outside cold is today?","category":"incorrect word order","reason":"While these words are related, they are not in the right order for English grammar; 'is' should come before the subject in a question."},"",{"choice":"Today coldoutside?","category":"missing verb","reason":"This phrase lacks a linking verb like 'is' to connect the time 'today' to the description 'cold'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":217,"sourceFile":"Basic-5_Writing strategies_Application_Style.pdf","sourceQuestionNumber":4,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A complete sentence requires a subject (who or what the sentence is about) and a predicate (the action or state of being) to make sense on its own.","example":"Incomplete: Running fast. Complete: He is running fast. Incomplete: The big red. Complete: The big red ball is mine.","strategyClue":"Look for a word that tells you who or what is doing the action (the subject) and a word that tells you the action or state (the verb); if either is missing, it is not a complete thought.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0218","version":4,"contentHash":"sha256:839a2adf8c8617ee79fea3d699e85709a9b90d0a95f5ee8e1e9d9f050e213f1f","question":"Identify the best example of a comparison.","choices":["The shadow followed me.","The wind whipped at my face.","The water is as smooth as glass.","The rain pounded the roof."],"correct":2,"explanation":{"correct":"Answer: The water is as smooth as glass. This sentence uses a simile to compare the water to glass using the word 'as'.","incorrect":[{"choice":"The shadow followed me.","category":"personification of object","reason":"This sentence describes an action, but it does not compare two different things to show how they are alike."},{"choice":"The wind whipped at my face.","category":"action verb usage","reason":"While this sentence uses vivid language, it describes an event rather than drawing a comparison between two objects or ideas."},"",{"choice":"The rain pounded the roof.","category":"descriptive sentence","reason":"This is a descriptive sentence about the rain, but it does not link two items to highlight a shared quality."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":218,"sourceFile":"Proficient-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":2,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A comparison, such as a simile, describes one thing by stating it is similar to something else using words like 'like' or 'as'.","example":"He is as tall as a tree. She runs like the wind. The clouds were like fluffy pillows.","strategyClue":"Look for a sentence that puts two different items side-by-side to highlight how they share a specific quality, often using connecting words that suggest similarity.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0219","version":4,"contentHash":"sha256:f463676ef14f3a12d1f841962547a79a26dcc2c3147e907982de0f52dfe2d426","question":"Which sentence is NOT a run- on?","choices":["The weather was dreadful it rained all day.","Before dinner last night, I went to the store and I bought chicken and squash.","During our afternoon recess, the teacher gave us each a treat.","The tree grew in our yard I climbed it every day one summer."],"correct":2,"explanation":{"correct":"Answer: During our afternoon recess, the teacher gave us each a treat. This sentence is correct because it contains one complete thought with a clear subject and verb, punctuated properly.","incorrect":[{"choice":"The weather was dreadful it rained all day.","category":"missing punctuation","reason":"This is a run-on because two complete sentences ('The weather was dreadful' and 'it rained all day') are mashed together without a comma or conjunction."},{"choice":"Before dinner last night, I went to the store and I bought chicken and squash.","category":"missing comma","reason":"This is a run-on because it joins two independent clauses with 'and' but fails to include a comma before the conjunction to separate the two main ideas."},"",{"choice":"The tree grew in our yard I climbed it every day one summer.","category":"fused sentences","reason":"This is a run-on sentence because it connects two separate statements ('The tree grew in our yard' and 'I climbed it every day') without any punctuation to mark the break."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":219,"sourceFile":"Proficient-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A run-on sentence happens when two or more complete thoughts are joined together incorrectly without proper punctuation or connecting words.","example":"Run-on: I am tired I will sleep. Correct: I am tired; I will sleep. Or: I am tired, so I will sleep.","strategyClue":"Read each sentence aloud and listen for a natural pause where one complete thought ends and a new one begins; if you find two complete sentences stuck together without a comma or semicolon, it is a run-on.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0220","version":5,"contentHash":"sha256:c946a1ca4822fc936978f658df0d4e7a993fbdea9ea860b4cc86ba4a006ac465","question":"Which letter closing is punctuated correctly?","choices":["Lat er-","See ya dude!","Regrettably.","Truly yours,"],"correct":3,"explanation":{"correct":"Answer: Truly yours,. In a formal letter closing, the first word is capitalized, the second word is lowercase, and it must end with a comma.","incorrect":[{"choice":"Lat er-","category":"informal closing error","reason":"This is not a standard letter closing and uses an incorrect hyphen instead of a comma. Always use formal phrases like 'Sincerely' or 'Truly yours' in a letter."},{"choice":"See ya dude!","category":"slang and punctuation","reason":"This is too casual for a letter closing and uses an exclamation point. Letter closings should be professional and end with a comma."},{"choice":"Regrettably.","category":"incorrect punctuation mark","reason":"While this is a formal word, it ends with a period. All letter closings require a comma at the end."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":220,"sourceFile":"Proficient-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":7,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A letter closing should start with a capital letter, use a comma at the end, and be professional in tone.","example":"Sincerely, / Yours truly, / Best regards,","strategyClue":"Check the capitalization of the first word, ensure the tone is professional, and look for the specific punctuation mark required after the closing phrase.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0221","version":4,"contentHash":"sha256:d3c535656cfeafdc4b2a29483f37c6f45aa78cd3b24e6b15143849033c640c3a","question":"Which sentence uses parallelism?","choices":["After Todd answered the phone, the doorbell rang.","Todd is my nephew who answered the phone.","Todd is a tall boy and he loves to talk.","Todd walked his dog, scratched his head, and sipped his cola."],"correct":3,"explanation":{"correct":"Answer: Todd walked his dog, scratched his head, and sipped his cola. This sentence uses parallelism because it uses the same verb form ('walked', 'scratched', 'sipped') for every item in the list, creating a balanced and smooth flow.","incorrect":[{"choice":"After Todd answered the phone, the doorbell rang.","category":"lacks list structure","reason":"This sentence is a complex sentence with a dependent clause, but it doesn't contain a list of actions that need to be balanced with parallel structure."},{"choice":"Todd is my nephew who answered the phone.","category":"lacks list structure","reason":"This sentence describes Todd using a relative clause, but it doesn't list multiple actions or items that require parallel verb forms."},{"choice":"Todd is a tall boy and he loves to talk.","category":"clunky clause structure","reason":"This sentence connects two different types of clauses ('Todd is...' and 'he loves...'). It does not use the same grammatical form on both sides of the conjunction to create parallelism."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":221,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":3,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Parallelism means using the same grammatical pattern for words, phrases, or clauses in a list to make your writing balanced and easy to read.","example":"Correct: She likes running, jumping, and swimming. Incorrect: She likes to run, jumping, and swimming.","strategyClue":"Look for a list of items or actions in the sentence. Check if every item in that list starts with the same kind of word or uses the same verb tense.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0222","version":4,"contentHash":"sha256:8a764f8b356d644993d3a1ffed569c6d99c241a774085e06fe5e81124f3aafcd","question":"Which is a complete sentence?","choices":["At the party, the band played songs.","On the way to Idaho for the holiday.","After dinner but before going to bed.","Dancing around the house."],"correct":0,"explanation":{"correct":"Answer: At the party, the band played songs. A complete sentence must have a subject (who or what the sentence is about) and a predicate (what the subject is doing). This sentence includes the subject 'the band' and the verb 'played'.","incorrect":["",{"choice":"On the way to Idaho for the holiday.","category":"missing subject and verb","reason":"This is a prepositional phrase, not a sentence. It explains where something is happening, but it does not tell us who or what is on the way."},{"choice":"After dinner but before going to bed.","category":"missing subject and verb","reason":"This phrase tells us when an action happens, but it lacks the necessary subject and action verb to function as a complete thought."},{"choice":"Dancing around the house.","category":"missing independent subject","reason":"This is a participle phrase. While it contains an action, it lacks a noun to perform the action. We don't know who is doing the dancing."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":222,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":4,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A complete sentence must contain a subject and a verb and express a complete thought. If you can't find who is doing the action, the sentence is incomplete.","example":"Incomplete: Running fast. Complete: The dog is running fast. Incomplete: In the park. Complete: We played in the park.","strategyClue":"Ask yourself 'Who or what?' and 'What happened?'. If you cannot find both pieces of information in the phrase, it is likely just a fragment.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0223","version":4,"contentHash":"sha256:dad4e6a06048df73f8e7d180317a7b8f3764737bb7a7fd347bf60421e5fe73e7","question":"How can you make a complete sentence? __________ swerved ________ around the corner __________. A B C","choices":["Put the words “The car” in space A.","Put the word “clear” in space B.","Put the words “in a hurry” in space C.","Put the word “And” in space A."],"correct":0,"explanation":{"correct":"Answer: Put the words “The car” in space A. A complete sentence must have a subject (who or what the sentence is about) and a predicate (what the subject is doing). “The car” serves as the subject, allowing the sentence to express a complete thought.","incorrect":["",{"choice":"Put the word “clear” in space B.","category":"missing subject","reason":"Placing 'clear' in space B does not provide a subject for the sentence. Without a noun like 'car' or 'truck' in space A, we don't know what is doing the action of swerving."},{"choice":"Put the words “in a hurry” in space C.","category":"missing subject","reason":"Adding 'in a hurry' to the end of the sentence adds extra detail, but it does not fix the missing subject at the beginning. A sentence still requires a 'who' or 'what' to be complete."},{"choice":"Put the word “And” in space A.","category":"incomplete subject","reason":"Starting with 'And' creates a fragment. Even though it is a word, it does not identify the 'who' or 'what' performing the action of swerving."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":223,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A complete sentence must have both a subject (a person, place, or thing) and a predicate (an action or state of being) to express a full idea.","example":"Incomplete: Swerved away. Complete: The truck swerved away. Incomplete: Ran fast. Complete: My brother ran fast.","strategyClue":"Ask yourself 'Who or what?' is performing the action in the sentence. If you cannot answer that question using the words in the sentence, you are missing the subject.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0224","version":4,"contentHash":"sha256:da670cfb4515808685f46008e209086572d902dd293772d9703b4e469e8a29d4","question":"Which word can be used in place of the underlined words? Receiving the award was exciting for Steve and Shelly.","choices":["we","them","they","her"],"correct":1,"explanation":{"correct":"Answer: them. The phrase 'for Steve and Shelly' acts as the object of the preposition 'for.' Because 'them' is an object pronoun, it is the correct choice to replace the names.","incorrect":[{"choice":"we","category":"subject pronoun error","reason":"'We' is a subject pronoun used to perform an action. Since Steve and Shelly are receiving the action of the preposition 'for,' you cannot use 'we'."},"",{"choice":"they","category":"subject pronoun error","reason":"'They' is a subject pronoun used for the people doing the action. It cannot be used as the object after a preposition like 'for'."},{"choice":"her","category":"pronoun number disagreement","reason":"'Her' is singular and refers to only one person. Because the sentence refers to two people, Steve and Shelly, you need a plural pronoun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":224,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Object pronouns are used after action verbs or prepositions like 'to,' 'with,' or 'for' to show who is receiving the action.","example":"Give it to me (not I). She went with us (not we). He bought a gift for them (not they).","strategyClue":"Cover the names in the sentence and try each option one by one. Ask yourself if the pronoun is being used to show who is receiving the action or if it is being used to perform the action.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0225","version":4,"contentHash":"sha256:5d7ed9b56d27bf020bf7cd7dd555ee689d88c00cc71c831e39718072d47c8776","question":"Which linking verb fits best in the sentence belo w? Sally and Harry ________ the president and vice-presidentof the senior class.","choices":["loo k","seem","is","are"],"correct":3,"explanation":{"correct":"Answer: are. The subject 'Sally and Harry' is plural, meaning there are two people. In the present tense, the plural subject requires the linking verb 'are'.","incorrect":[{"choice":"loo k","category":"incorrect verb choice","reason":"While 'look' is a verb, the sentence structure requires a state-of-being linking verb to equate the subjects with their titles, making 'are' the correct choice."},{"choice":"seem","category":"incorrect verb choice","reason":"The word 'seem' implies an opinion or appearance, but the sentence is stating a factual identity. Use 'are' to define exactly what Sally and Harry are."},{"choice":"is","category":"subject-verb disagreement","reason":"'Is' is a singular linking verb. Because the subject is 'Sally and Harry' (two people), you must use the plural form 'are' instead."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":225,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A linking verb connects the subject to a noun or adjective that describes it. The verb must match the number of the subject (singular or plural).","example":"He is a teacher (singular); They are students (plural); The cat is hungry (singular); The kittens are playful (plural).","strategyClue":"Count how many people or things are in the subject. If there is more than one, check which verb form matches a plural group.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0226","version":4,"contentHash":"sha256:3df3d2b7a1dddeb20d4a037cbf3594106562de827f15d0c4fcbef02296ff3bca","question":"In which section of the newspaper or online news would this article a ppear? “Sunny Today Turning to Partly Cloudy”","choices":["sp orts","weather","horoscope","community"],"correct":1,"explanation":{"correct":"Answer: weather. The headline 'Sunny Today Turning to Partly Cloudy' describes atmospheric conditions and temperature, which are the primary focus of a weather report.","incorrect":[{"choice":"sp orts","category":"mismatched content topic","reason":"Sports sections focus on games, scores, and athletes. Weather information about sun and clouds does not belong in this section."},"",{"choice":"horoscope","category":"mismatched content topic","reason":"Horoscope sections provide predictions based on zodiac signs. Forecasts about the sky are not related to astrology or personality signs."},{"choice":"community","category":"mismatched content topic","reason":"Community sections cover local events, neighborhood news, and schools. While weather affects the community, the headline itself is a technical report on current conditions."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":226,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":21,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Newspaper sections categorize information by topic so readers can find news easily. Each section has a specific purpose and type of content.","example":"Sports: scores and game recaps; Weather: temperature and sky conditions; Editorial: opinions and arguments.","strategyClue":"Look for keywords in the headline that signal a specific topic, then ask yourself which section is dedicated to reporting those types of facts.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0227","version":5,"contentHash":"sha256:6bb0d771822582666686c8612b2f181a66a0c82e9ad52794e9e93048376db2b7","question":"Choose the correct verb. Kids throwing rocks _____ all the windows in that shack.","choices":["h as broken","have broke","have broken","has breaked"],"correct":2,"explanation":{"correct":"Answer: have broken. The subject 'Kids' is plural, so it requires the plural verb 'have' and the correct past participle form 'broken'.","incorrect":[{"choice":"h as broken","category":"subject-verb disagreement","reason":"The subject 'Kids' is plural. 'Has' is singular, so it cannot be used with a plural subject like 'Kids'."},{"choice":"have broke","category":"incorrect verb form","reason":"When using 'have' to form the perfect tense, you must use the past participle 'broken' rather than the simple past 'broke'."},"",{"choice":"has breaked","category":"verb conjugation error","reason":"'Breaked' is not a word in English. The past participle of 'break' is 'broken', and 'has' does not agree with the plural subject 'Kids'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":227,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To form the present perfect tense, use 'has' for singular subjects and 'have' for plural subjects, followed by the past participle of the verb.","example":"He has eaten (singular), They have eaten (plural), I have broken (correct vs incorrect: I have broke).","strategyClue":"First, identify if the subject is singular or plural. Second, decide which past participle correctly describes the action of breaking.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0228","version":4,"contentHash":"sha256:4585852739aa18615a022c816c2f17c0f8a6edc01f8a51f599594029d85c0704","question":"Choose the underlined phrase that tells “which”.","choices":["By the time I finish my chores, it will be time to go.","The dress with the long sleeves is my favorite one.","Before noon we’d already eaten lunch.","Look under the blankets for the pajamas."],"correct":1,"explanation":{"correct":"Answer: The dress with the long sleeves is my favorite one. The phrase 'with the long sleeves' acts as an adjective because it describes 'which' specific dress is the speaker's favorite.","incorrect":[{"choice":"By the time I finish my chores, it will be time to go.","category":"adverbial time clause","reason":"This phrase describes 'when' the action will happen rather than 'which' item is being discussed."},"",{"choice":"Before noon we’d already eaten lunch.","category":"prepositional time phrase","reason":"This phrase identifies the time that the action occurred, answering 'when' rather than identifying a specific noun."},{"choice":"Look under the blankets for the pajamas.","category":"prepositional place phrase","reason":"This phrase describes 'where' to look, not 'which' specific object to identify."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":228,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":43,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An adjective phrase describes a noun by telling us 'which one,' 'what kind,' or 'how many.'","example":"The book on the shelf (which book?), The girl with the red hat (which girl?), The house by the lake (which house?)","strategyClue":"Find the noun in the sentence and ask yourself if the underlined part points to a specific one among many. If the phrase answers 'when' or 'where,' it is likely not the one answering 'which.'","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0229","version":4,"contentHash":"sha256:5e941f0ec16409d16d7e386a8a49050232d7a780cb356ae58edd6853c1ad9a89","question":"Choose the correct words to complete the sentence. Several _______ of apples ____ _ _______ at the market.","choices":["cases, w ere sold","case, was sold","cases, were saled","case, were selled"],"correct":0,"explanation":{"correct":"Answer: cases, were sold. Since 'several' indicates more than one, the subject 'cases' is plural, requiring the plural verb 'were'. Additionally, the past participle of 'sell' is 'sold', not 'saled' or 'selled'.","incorrect":["",{"choice":"case, was sold","category":"subject-verb disagreement","reason":"The word 'several' means there is more than one. Therefore, you need the plural noun 'cases' and the plural verb 'were' instead of the singular 'case' and 'was'."},{"choice":"cases, were saled","category":"irregular verb error","reason":"'Saled' is not a real word. The verb 'sell' is irregular; its past participle form is 'sold', not 'saled'."},{"choice":"case, were selled","category":"subject-verb and verb form error","reason":"You need a plural subject for 'several' and the correct past tense of 'sell'. 'Case' is singular and 'selled' is not the correct way to write the past tense of 'sell'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":229,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":46,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Subject-verb agreement requires singular subjects to take singular verbs and plural subjects to take plural verbs. Some verbs are irregular and change their form completely in the past tense.","example":"One cat walks, two cats walk; The store sold apples, he bought a pear.","strategyClue":"Look for quantifier words like 'several' or 'many' to determine if the subject is plural, then check if the action word follows standard English patterns for past tense.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0230","version":4,"contentHash":"sha256:7e6657100bd372213d7dfbfce3283c26e2ee8559f0484b09b419fc1df50e2716","question":"Which sentence is a run-on sentence?","choices":["M andy ran a marathon. She absolutely loved it.","Mandy ran a marathon she absolutely loved it.","Ma ndy ran a marathon, and she absolutely loved it.","When Mandy ran a marathon, she absolutely loved it."],"correct":1,"explanation":{"correct":"Answer: Mandy ran a marathon she absolutely loved it. A run-on sentence occurs when two complete thoughts are joined together without any punctuation or connecting words to separate them.","incorrect":[{"choice":"M andy ran a marathon. She absolutely loved it.","reason":"She absolutely loved it. \"M andy ran a marathon. She absolutely loved it.\" misses the writing job in the prompt because it is off topic, too vague, the wrong tone, or the wrong sentence part."},"",{"choice":"Ma ndy ran a marathon, and she absolutely loved it.","reason":"\"Ma ndy ran a marathon, and she absolutely loved it.\" misses the writing job in the prompt because it is off topic, too vague, the wrong tone, or the wrong sentence part."},{"choice":"When Mandy ran a marathon, she absolutely loved it.","category":"complex sentence","reason":"This is a correct complex sentence because the word 'When' creates a dependent clause, which is properly separated from the rest of the sentence by a comma."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":230,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":48,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A run-on sentence happens when two independent thoughts (complete sentences) are smashed together without a period, semicolon, or a comma plus a conjunction.","example":"Run-on: The dog barked it was hungry. Correct: The dog barked. It was hungry. OR The dog barked, for it was hungry.","strategyClue":"Look for two subjects and two verbs acting as complete thoughts within one sentence. If you find two complete sentences joined by nothing, you have identified a run-on.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0231","version":4,"contentHash":"sha256:c27358690f21b6ab7876b74de75cc30a3d3c19560645981755390deaf516d7d5","question":"You broke a window with a baseball. From whose pointof view would you tell about it?","choices":["the owner of the house","your own","the neighbor who saw it","your parents"],"correct":1,"explanation":{"correct":"Answer: your own. The question asks who is telling the story about the window you broke, and since the prompt uses 'you' to describe your action, the perspective must be first-person from your own point of view.","incorrect":[{"choice":"the owner of the house","category":"wrong perspective","reason":"Choosing this point of view would change the narrator to the person who owns the window, which is not who the sentence is describing as the one who broke it."},"",{"choice":"the neighbor who saw it","category":"wrong perspective","reason":"This narrator would be an outside observer watching the event happen, rather than the person who actually swung the baseball."},{"choice":"your parents","category":"wrong perspective","reason":"While your parents might know about the incident, they are not the ones who broke the window, so they would be telling the story about you, not as you."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":231,"sourceFile":"Proficient-2_Writing strategies_Application_Style.pdf","sourceQuestionNumber":7,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Point of view is the perspective from which a story is told. 'First-person' uses 'I' and 'me' to describe one's own experiences.","example":"First-person: 'I kicked the ball.' Third-person: 'He kicked the ball.'","strategyClue":"Identify the person who performed the action in the prompt. Since the sentence asks about a choice *you* made, think about which perspective places you inside the character's thoughts and actions.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0232","version":4,"contentHash":"sha256:269891c8cb537acfccf3fe986d66556dc850be9057e995cff48be2fef7d70d13","question":"Which word can replace the underlined words? The small boat tippedover in the lake during the storm.","choices":["yacht","sail","kayak","barge"],"correct":2,"explanation":{"correct":"Answer: kayak. A kayak is a specific type of small, narrow boat that fits the description of the underlined words perfectly.","incorrect":[{"choice":"yacht","category":"mismatched boat size","reason":"A yacht is typically a large, expensive vessel used for pleasure cruising, not a 'small boat'."},{"choice":"sail","category":"wrong part of speech","reason":"A 'sail' is a piece of fabric used to catch the wind; it is a part of a boat, not the boat itself."},"",{"choice":"barge","category":"inaccurate vessel type","reason":"A barge is a long, flat-bottomed boat used for carrying heavy goods, which is very different from a small, maneuverable boat."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":232,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A synonym is a word that has the same or a very similar meaning to another word. Choosing the right synonym helps make your writing more precise.","example":"Small: tiny, little, petite; Boat: vessel, craft, ship","strategyClue":"Think about the main purpose and size of the object described. Eliminate options that represent different types of items or drastically different sizes.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0233","version":4,"contentHash":"sha256:6b2620515d79f5dd141b9402040b445e98e2b0ee02c861afa05586d4dfc3cae4","question":"Choose the last step that is listed for how to a change a light bulb.","choices":["Turn off the light.","Unscrew the burned-out bulb.","Put the shade back on.","Findout what kindof bulb you need."],"correct":2,"explanation":{"correct":"Answer: Put the shade back on. This is the final action in the sequence because the light bulb has already been replaced and the lamp is being restored to its original state.","incorrect":[{"choice":"Turn off the light.","category":"sequencing error","reason":"Turning off the light is the very first step you must take for safety before you even begin to touch the light bulb."},{"choice":"Unscrew the burned-out bulb.","category":"sequencing error","reason":"This is a middle step that happens after the light is turned off but before you can put the new bulb in."},"",{"choice":"Findout what kindof bulb you need.","category":"sequencing error","reason":"This is a preparatory step that must happen before you start the physical process of changing the bulb."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":233,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":22,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Sequential order describes the steps of a process in the exact order they should happen, starting from the beginning and moving to the end.","example":"First, break the egg. Second, mix it. Third, cook it.","strategyClue":"Think about the physical logic of the task: what must be done first to stay safe, and what is the very last thing you would do before the lamp is ready to use again?","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0234","version":4,"contentHash":"sha256:0f6c976b783602ea1948b2b5b7d69cfe6f5c3ff10f949f318ea4f7061d88b75f","question":"Which sentence is correct?","choices":["No, Lexi hasn’t answer the phone yet.","The snake slithering into the shed andoutof the sun.","Breakfast in bed is my favorite birthday treat every year.","The three boys takes turns on the slide at the corner playground."],"correct":2,"explanation":{"correct":"Answer: Breakfast in bed is my favorite birthday treat every year. This sentence is grammatically correct because the singular subject 'Breakfast' agrees with the singular verb 'is'.","incorrect":[{"choice":"No, Lexi hasn’t answer the phone yet.","category":"verb tense error","reason":"The helping verb 'hasn’t' needs to be followed by the past participle 'answered' instead of the base form 'answer'."},{"choice":"The snake slithering into the shed andoutof the sun.","category":"missing main verb","reason":"This sentence is a fragment because it lacks a main action verb to tell us what the snake did. Also, 'andoutof' is missing spaces."},"",{"choice":"The three boys takes turns on the slide at the corner playground.","category":"subject-verb disagreement","reason":"The subject 'The three boys' is plural, so it requires the plural verb 'take' instead of the singular 'takes'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":234,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A sentence must have a subject and a verb that agree in number, and the verbs must be in the correct tense form.","example":"Correct: The dogs run. Incorrect: The dogs runs. Correct: She has eaten. Incorrect: She has eat.","strategyClue":"Check each sentence for a clear subject and a matching action. If the subject is plural, make sure the verb doesn't end in 's'; if the sentence feels incomplete, look for the missing action word.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0235","version":5,"contentHash":"sha256:14731dffa4dd062c6362f6a9303635029bd8392d8eab1532469321db36052c79","question":"Which thing does not belong?","choices":["haircut","beard","eyebrow","mustache"],"correct":0,"explanation":{"correct":"Answer: haircut. A haircut is a process of removing hair from the scalp, while beards, eyebrows, and mustaches are all types of facial hair.","incorrect":["",{"choice":"beard","category":"facial hair","reason":"A beard is a type of facial hair that grows on the chin and cheeks, so it does belong in a group focused on hair on the face."},{"choice":"eyebrow","category":"facial hair","reason":"An eyebrow is a patch of hair located above the eye, which is a feature of the face, making it part of the facial hair category."},{"choice":"mustache","category":"facial hair","reason":"A mustache is hair that grows on the upper lip, which is on the face, fitting perfectly into the facial hair group."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":235,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":27,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To find the item that does not belong, identify the common category that the other three items share.","example":"Group (Apple, Banana, Carrot, Orange): Carrot does not belong because it is a vegetable, not a fruit.","strategyClue":"Label each item as either 'on the face' or 'not on the face' to see which one stands out from the rest of the group.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0236","version":4,"contentHash":"sha256:8e5e06f24164e8f91b6a8b507a94edd39eeead2957d69d48a29c08ae0f633fd1","question":"Choose the words that best complete the following sentence. The flood waters came _____________ down the hill after the hard rainstorm.","choices":["quietly flowing","slowing rolling","suddenly roaring","quickly floating"],"correct":2,"explanation":{"correct":"Answer: suddenly roaring. The word 'suddenly' describes the speed of the flood waters, and 'roaring' matches the loud, powerful sound often associated with flood waters.","incorrect":[{"choice":"quietly flowing","category":"inconsistent tone","reason":"Flood waters are usually loud and violent. Describing them as 'quietly flowing' does not make sense for the context of a hard rainstorm."},{"choice":"slowing rolling","category":"mismatched action","reason":"Flood waters move rapidly during a storm. 'Slowing' is the opposite of the speed you would expect to see after a hard rain."},"",{"choice":"quickly floating","category":"imprecise verb choice","reason":"'Floating' is used for objects resting on top of water, whereas flood waters themselves 'roar' or 'rush' down a hill."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":236,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Adverbs describe actions (verbs), while verbs describe the action itself. Choosing the right pair helps create a clear picture of what is happening.","example":"The wind howled loudly vs. The wind whispered softly.","strategyClue":"Visualize the scene of a storm. Ask yourself if the water's speed and sound match the intensity of the rain described in the sentence.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0237","version":4,"contentHash":"sha256:7ba24503cc641d986bf02169cb6acb51a3ab1a3714dd7f97d8d5c1035bb60f61","question":"Which of the following would be included under the topic of eating breakfast?","choices":["fish","mustard","syrup","icing"],"correct":2,"explanation":{"correct":"Answer: syrup. Syrup is a common topping for breakfast foods like pancakes or waffles, making it the most appropriate choice for this category.","incorrect":[{"choice":"fish","category":"uncommon breakfast food","reason":"While fish can be eaten at any time, it is not typically associated with the standard category of 'breakfast' in the way that syrups and sweet toppings are."},{"choice":"mustard","category":"incorrect condiment category","reason":"Mustard is a savory condiment used for lunch or dinner sandwiches, whereas breakfast items usually favor sweet or neutral toppings."},"",{"choice":"icing","category":"dessert food category","reason":"Icing is specifically used for cakes and cookies, which fall under the category of desserts or treats, rather than standard breakfast items."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":237,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":33,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A category is a group of things that share similar features, uses, or times of day. Grouping items helps us understand how they relate to one another.","example":"Breakfast: eggs, toast, oatmeal. School supplies: pencils, erasers, notebooks.","strategyClue":"Visualize sitting at a kitchen table in the morning. Imagine which of the items would realistically appear on a plate during that specific mealtime.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0238","version":4,"contentHash":"sha256:2dd45444dced752135d782f1d00c7f624032e173b028bc7685ce5d8547dee30b","question":"Choose the best wordor words to complete the sentence. Adrian used the broken pinecones _____ a wreath for his mom.","choices":["making","to made","will make","to make"],"correct":3,"explanation":{"correct":"Answer: to make. This is an infinitive phrase used to show purpose. We use the word 'to' followed by the base form of the verb when explaining why someone performed an action.","incorrect":[{"choice":"making","category":"gerund vs infinitive","reason":"Using 'making' here creates a fragment that doesn't clearly explain the purpose. We use 'to' + base verb to show the reason behind Adrian's action."},{"choice":"to made","category":"incorrect verb form","reason":"You cannot combine 'to' with the past tense 'made'. The infinitive form should always use the base form of the verb, which is 'make'."},{"choice":"will make","category":"verb tense error","reason":"Using 'will make' changes the meaning of the sentence. Since the rest of the sentence is in the past tense ('used'), 'will make' creates a confusing mix of time periods."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":238,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":39,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An infinitive is formed by adding 'to' to the base form of a verb. It is often used to explain the reason or purpose for an action.","example":"I went to the store to buy milk. She practiced to get better. He used a hammer to fix the chair.","strategyClue":"Ask yourself: 'Why did Adrian use the pinecones?' If the answer starts with 'to' and a verb that tells you the purpose, that is likely the correct structure.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0239","version":4,"contentHash":"sha256:3cafe02bea7a5dc540d5f4aae1e4d59d7adb90612992c5fe695034997fe035b4","question":"What/who is the subjectof this sentence? Before we went to the park, Olive had to change her clothes.","choices":["we","park","Olive","clothes"],"correct":2,"explanation":{"correct":"Answer: Olive. The subject is the person, place, or thing performing the action in the main clause. In this sentence, Olive is the one performing the action of changing her clothes.","incorrect":[{"choice":"we","category":"subordinate clause subject","reason":"While 'we' is a subject, it is located in the introductory clause ('Before we went to the park'), not the main clause of the sentence."},{"choice":"park","category":"object of preposition","reason":"The 'park' is where the action happens, but it is the object of the preposition 'to' in the first part of the sentence, not the subject performing the main action."},"",{"choice":"clothes","category":"direct object","reason":"'Clothes' is what Olive is changing. This is the direct object receiving the action, not the subject performing the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":239,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The subject is the person or thing that is doing the action in a sentence. You can find it by asking 'Who or what?' before the verb.","example":"Sarah (subject) runs. The dog (subject) chased the ball.","strategyClue":"Split the sentence into the introductory phrase and the main clause. Ignore the part before the comma and look for the noun that is performing the action in the second half.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0240","version":4,"contentHash":"sha256:3026bf0f67fbc67810b5938061e484847be35205e6ea16980137dcadd29b053d","question":"What is the subjectof the sentence? On a cold, frosty morning, the ice cracked as we walkedon it.","choices":["morning","ice","we","it"],"correct":1,"explanation":{"correct":"Answer: ice. The subject is the person, place, or thing that is performing the action or being described by the verb. In this sentence, the 'ice' is the thing doing the action of cracking.","incorrect":[{"choice":"morning","category":"prepositional phrase object","reason":"The word 'morning' appears inside a prepositional phrase ('On a cold, frosty morning'). It tells us when the action happened, not who or what is performing the action."},"",{"choice":"we","category":"subject of dependent clause","reason":"While 'we' is a subject, it belongs to the second part of the sentence ('as we walked on it'). The main subject of the sentence's primary action is the object that cracked."},{"choice":"it","category":"object of preposition","reason":"The word 'it' is a pronoun that comes after the preposition 'on'. It acts as an object here, not as the subject performing the action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":240,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":50,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The subject is the main noun or pronoun that performs the action of the verb or is the main topic of the sentence.","example":"The dog barked. (Subject: dog). The blue car raced by. (Subject: car).","strategyClue":"Find the verb—the action word—first. Ask yourself 'Who or what?' before that verb to identify the person or object performing the action.","link":"","linkText":""}},{"id":"grammar-revising-editing-strategy-q0241","version":4,"contentHash":"sha256:26bd282da524b36977d82204958b733fe0d2ade49ce382a7ff0b3d06296d5dff","question":"Which is another way to write this sentence? The terrifying dog growled menacingly at me as I slowly backed up towar d the crumbling building.","choices":["I slo wly crumbled toward the menacing building as the slow dog terrified me.","The crumbled dog terrified me slowly as I backed up towar d the menacing building.","I slowly backed up toward the crumbling building as the terrifying dog growled menacingly at me.","The terrified dog menaced me slowly as I cr umbled toward the growling building."],"correct":2,"explanation":{"correct":"Answer: I slowly backed up toward the crumbling building as the terrifying dog growled menacingly at me. This choice correctly maintains the original meaning by moving the second half of the sentence to the front while keeping the same verbs and descriptions.","incorrect":[{"choice":"I slo wly crumbled toward the menacing building as the slow dog terrified me.","category":"changes sentence meaning","reason":"This version changes the meaning by suggesting that the building crumbled and the dog was slow. Always ensure your rewritten sentence keeps the same details as the original."},{"choice":"The crumbled dog terrified me slowly as I backed up towar d the menacing building.","category":"changes descriptive adjectives","reason":"This changes 'terrifying dog' to 'crumbled dog' and 'menacing building' to 'menacing'. Swapping adjectives changes the specific scene you are describing."},"",{"choice":"The terrified dog menaced me slowly as I cr umbled toward the growling building.","category":"swapped roles and actions","reason":"In this version, the dog is 'terrified' instead of 'terrifying', and the building is 'growling'. Check that your rewrite keeps the action connected to the correct person or object."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-revising-editing-strategy","sequence":241,"sourceFile":"Proficient-3_Writing strategies_Application_Style.pdf","sourceQuestionNumber":4,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"You can rewrite a sentence by changing the order of the clauses as long as the meaning and the descriptive words remain the same.","example":"Original: I ate an apple after school. Rewrite: After school, I ate an apple.","strategyClue":"Break the original sentence into two parts: the main action and the time or reason. Try swapping the order of these two parts, but keep every word describing the objects or actions exactly as they were in the original.","link":"","linkText":""}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["grammar-revising-editing-strategy"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["grammar-revising-editing-strategy"] = chunkSet;
  }
})();
